# TDD plan item 10: audio cut timestamp parenthetical -> non-speech
NON_SPEECH_AUDIO_CUT_RE = re.compile(
    r"(?i)audio\s+(abruptly\s+)?cut\s+\d{2}:\d{2}:\d{2}-\d{2}:\d{2}:\d{2}"
)
ORDINAL_SUFFIX_RE = re.compile(r"^(\d+)(st|nd|rd|th)$", re.IGNORECASE)

# Max content length to run Levenshtein vs NON_SPEECH_BRACKET_CONTENT. Edited by Cursor (plan: 2 Lev).
_NON_SPEECH_LEV_MAX_LEN = 60
_NON_SPEECH_LEV_MAX = 2


def is_non_speech_content(content_norm: str) -> bool:
    """Return True if exact match, keyword, audio cut, or within 2 Lev of allowlist. Edited by Cursor (plan)."""
    if content_norm in NON_SPEECH_BRACKET_CONTENT:
        return True
    if any(kw in content_norm for kw in NON_SPEECH_KEYWORDS):
        return True
    if NON_SPEECH_AUDIO_CUT_RE.search(content_norm):
        return True
    if len(content_norm) <= _NON_SPEECH_LEV_MAX_LEN:
        from scripts.typo_distances import levenshtein_distance  # noqa: PLC0415

        for phrase in NON_SPEECH_BRACKET_CONTENT:
            if levenshtein_distance(content_norm, phrase) <= _NON_SPEECH_LEV_MAX:
                return True
    return False


def _digits_to_spoken(digit_str: str) -> list[str]:
    """Spoken form of digit string for codes: 640->six forty, 707->seven oh seven. Edited by Cursor."""
    result: list[str] = []
    if not digit_str or not digit_str.isdigit():
        return result
    n = int(digit_str)
    if len(digit_str) == 1:
        result = [digit_to_word(n)]
    elif len(digit_str) == 2:
        result = [number_to_words(n)]
    elif len(digit_str) == 3:
        if 10 <= n % 100 <= 99 and n % 10 == 0:
            result = [number_to_words(n // 100), number_to_words(n % 100)]
        else:
            result = [digit_to_word(int(d)) if d != "0" else "oh" for d in digit_str]
    elif len(digit_str) == 4:
        result = [
            number_to_words(int(digit_str[:2])),
            number_to_words(int(digit_str[2:])),
        ]
    else:
        result = [digit_to_word(int(d)) if d != "0" else "oh" for d in digit_str]
    return result


def _digit_run_options(digit_str: str) -> list[list[str]]:
    """Return alternative token lists for a digit run (digit-by-digit and grouped). Edited by Cursor (plan)."""
    if not digit_str or not digit_str.isdigit():
        return []
    n = int(digit_str)
    digit_by_digit = [digit_to_word(int(d)) if d != "0" else "oh" for d in digit_str]
    options: list[list[str]] = [digit_by_digit]
    if len(digit_str) == 2:
        options.append([number_to_words(n)])
    elif len(digit_str) == 3:
        if 10 <= n % 100 <= 99:
            options.append([number_to_words(n // 100), number_to_words(n % 100)])
    elif len(digit_str) == 4:
        options.append(
            [
                number_to_words(int(digit_str[:2])),
                number_to_words(int(digit_str[2:])),
            ]
        )
    return options


def normalize_digit_letter_mixed(span: str) -> list[str]:
    """Digit-letter mixed (2d, 77p0995e) -> spoken form(s). Edited by Cursor (plan: multiple forms)."""
    s = span.strip()
    if not s:
        return [span]
    parts: list[tuple[str, str]] = []
    i = 0
    while i < len(s):
        if s[i].isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            parts.append(("digits", s[i:j]))
            i = j
        elif s[i] in "({" and i + 1 < len(s):
            close = ")" if s[i] == "(" else "}"
            k = s.find(close, i + 1)
            if k != -1:
                inner = s[i + 1 : k].strip()
                if inner.isalpha():
                    # TDD plan item 4: multi-letter parens (ff) -> eff eff
                    for c in inner:
                        parts.append(("letter", c))
                    i = k + 1
                    continue
            i += 1
        elif s[i].isalpha():
            j = i
            while j < len(s) and s[j].isalpha():
                j += 1
            parts.append(("letter", s[i:j]))
            i = j
        else:
            i += 1
    option_sequences: list[list[str]] = [[]]
    for kind, val in parts:
        if kind == "digits":
            opts = _digit_run_options(val)
            if not opts:
                for seq in option_sequences:
                    seq.extend(_digits_to_spoken(val))
            else:
                new_seqs: list[list[str]] = []
                for seq in option_sequences:
                    for opt in opts:
                        new_seqs.append(seq + opt)
                option_sequences = new_seqs
        elif kind == "letter":
            toks = [LETTER_PRONUNCIATION.get(c.lower(), c) for c in val]
            for seq in option_sequences:
                seq.extend(toks)
    if not option_sequences or not option_sequences[0]:
        return [span]
    result_set: set[str] = set()
    for seq in option_sequences:
        result_set.add(" ".join(seq))
    result_list = list(result_set)
    primary = result_list[0]
    if (s.endswith("2s") or s.endswith("2S")) and " two ess" in primary:
        result_set.add(primary.replace(" two ess", " twos"))
        result_list = list(result_set)
    return result_list


def normalize_double_letter_parens(span: str) -> list[str]:
    """Two letters in parentheses (ph), (ab) -> pee aych, ay bee. Edited by Cursor (TDD item 5)."""
    s = span.strip()
    if len(s) < 4 or s[0] != "(" or s[-1] != ")":
        return [span]
    inner = s[1:-1].strip()
    if len(inner) != 2 or not inner.isalpha():
        return [span]
    a, b = inner[0].lower(), inner[1].lower()
    if a in LETTER_PRONUNCIATION and b in LETTER_PRONUNCIATION:
        return [f"{LETTER_PRONUNCIATION[a]} {LETTER_PRONUNCIATION[b]}"]
    return [span]


def normalize_single_letter_parens(span: str) -> list[str]:
    """Single letter in parentheses (with optional spaces) -> letter pronunciation."""
    s = span.strip()
    if len(s) < 3 or s[0] != "(" or s[-1] != ")":
        return [span]
    inner = s[1:-1].strip()
    if len(inner) != 1 or not inner.isalpha():
        return [span]
    letter = inner.lower()
    if letter in LETTER_PRONUNCIATION:
        return [LETTER_PRONUNCIATION[letter]]
    return [span]


def normalize_number_parens(span: str) -> list[str]:
    """Return spoken number for number in parentheses (e.g. (32)->thirty two)."""
    s = span.strip()
    if len(s) < 3 or s[0] != "(" or s[-1] != ")":
        return [span]
    inner = s[1:-1].strip()
    if not inner.isdigit():
        return [span]
    try:
        n = int(inner)
        if 0 <= n <= 999:
            return [number_to_words(n)]
    except (ValueError, KeyError):
        pass
    return [span]


